/* FDI-Z · Fase 62 · Uso de las armas de fuego: mira, munición en el HUD y animación con pistola. Todos los modos.
 * Se incrusta en la escena Juego con scripts/fase62_armas_uso.py (no editar el evento a mano):
 *   FDIZ-FASE62-MOD y FDIZ-FASE62-TICK arriba de todo, sin compuerta de host (cada máquina dibuja su mira y su HUD);
 *   FDIZ-FASE62-ANIM al final de "Combate: pegar" (host / sin red; la animación llega a los clientes por la red).
 *
 * Munición: es la de siempre (Sup.Usos, se gasta 1 por disparo y al llegar a 0 vuelven los puños). No hay recarga ni
 * balas de reserva: el HUD muestra las balas que le quedan al arma y, debajo del ícono, el cargador completo con las
 * gastadas en gris. CARGADOR = las balas con que se recoge cada arma (fase 59).
 * Mira: una cruz hueca de 11 px a 78 px del arma, hacia donde apunta (AimX, AimY); más transparente si queda sobre un
 * personaje o un zombi. Solo para jugadores (no bots) con arma de fuego, de pie, en juego y sin pausa.
 * Animación: con pistola (pequeña o sheriff) el golpe de lado o hacia abajo usa <personaje>_pistola_lado / _abajo; con escopeta,
 * de lado, <personaje>_escopeta_lado (fase 69: Tony usa sus animaciones de disparo de animaciones_gif/personajes/tony/).
 * Hacia arriba no hay animación de pistola: se queda la de pegar hacia arriba de siempre. Si un personaje no tiene la
 * animación de pistola, setAnimationName no cambia nada y sigue la de pegar (nunca queda invisible ni detenido).
 * Pistola inicial (fase 67): nadie empieza con ella. Al empezar la partida (host / sin red) se pone UNA pistola pequeña
 * en el piso (ArmaPiso Tipo "pistolita", Solo = 1) del salón donde está el jugador 1: B-01 (intro de Escape e Historia)
 * o E-04 (aparición normal: Jefe, en línea, Escape sin intro). Se recoge con el sistema de siempre ("Armas del salón":
 * pasar encima con los puños; solo el jugador 1 por Solo = 1), que la equipa con 9 balas y borra la del piso.
 * PistolaPuesta (variable de la escena) evita ponerla dos veces; se reinicia sola con la escena (partida nueva). */
(function (gdjs) {
  "use strict";
  if (gdjs.fdizArmas && gdjs.fdizArmas.VER === 2) return;
  const A = (gdjs.fdizArmas = { VER: 2 });

  A.CARGADOR = { pistolita: 9, pistola: 4, escopeta: 6 };
  A.PISTOLAS = { pistolita: true, pistola: true };
  A.RADIO = 78;                 // px del arma a la mira
  A.ALTO = 46;                  // el arma (y la salida de las balas) está 46 px arriba de los pies (fase 59)
  A.ICONO = { 1: [351, 94], 2: [1813, 94], 3: [351, 978], 4: [1813, 978] };   // ícono del arma (54 x 54) de cada panel
  A.BAJAS = 2;                  // con estas balas o menos, el número se pone rojo

  const VS = (o, n) => o.getVariables().get(n);
  const num = (o, n) => VS(o, n).getAsNumber();
  const str = (o, n) => VS(o, n).getAsString();
  const objs = (scn, n) => { try { return scn.getObjects(n) || []; } catch (e) { return []; } };
  const rol = (scn) => { try { return scn.getGame().getVariables().get("NetRol").getAsNumber(); } catch (e) { return 0; } };
  const SV = (scn, n) => scn.getVariables().get(n);
  A.deFuego = (s) => A.CARGADOR[str(s, "Arma")] !== undefined;

  // ------------------------------------------------------------------ animación (host / sin red)
  A.anim = function (scn) {
    if (rol(scn) === 2) return;
    for (const s of objs(scn, "Sup")) {
      const arma = str(s, "Arma");
      if (num(s, "Atacando") !== 1 || !(A.PISTOLAS[arma] || arma === "escopeta")) continue;
      const pj = str(s, "Personaje"), an = s.getAnimationName();
      // fase 69: con escopeta, de lado, <personaje>_escopeta_lado (Tony la tiene; los demás siguen con la de pegar)
      const tipo = arma === "escopeta" ? "escopeta" : "pistola";
      if (an === pj + "_pegar_lado") s.setAnimationName(pj + "_" + tipo + "_lado");
      else if (an === pj + "_pegar_abajo" && tipo === "pistola") s.setAnimationName(pj + "_pistola_abajo");
    }
  };

  // ------------------------------------------------------------------ mira
  const caja = (o) => {
    const x = o.getDrawableX ? o.getDrawableX() : o.getX(), y = o.getDrawableY ? o.getDrawableY() : o.getY();
    return [x, y, x + o.getWidth(), y + o.getHeight()];
  };
  const dentro = (b, x, y, m) => x >= b[0] - m && x <= b[2] + m && y >= b[1] - m && y <= b[3] + m;
  A.ZN = ["ZNormal", "ZCorredor", "ZGriton", "ZGordo", "ZConserje", "ZJoel", "ZJustino", "ZCanepa", "Profe"];
  A.posMira = function (s) {
    let ax = num(s, "AimX"), ay = num(s, "AimY");
    const n = Math.hypot(ax, ay);
    if (n < 0.01) return null;
    ax /= n; ay /= n;
    return [s.getX() + ax * A.RADIO, s.getY() - A.ALTO + ay * A.RADIO];
  };
  function miras(scn) {
    const juego = SV(scn, "Estado").getAsString() === "juego" && SV(scn, "Pausa").getAsNumber() !== 1;
    const sups = objs(scn, "Sup");
    const otros = sups.concat(...A.ZN.map((n) => objs(scn, n)));
    for (const s of sups) {
      const j = num(s, "Jugador");
      const ver = juego && j >= 1 && j <= 4 && num(s, "Control") !== -1 && str(s, "Estado") === "normal" && A.deFuego(s) && num(s, "Usos") > 0;
      const p = ver ? A.posMira(s) : null;
      let m = s.__fdizMira;
      if (!p) { if (m) m.hide(true); continue; }
      if (!m) {
        m = s.__fdizMira = scn.createObject("Mira");
        if (!m) continue;
        m.setLayer("Juego");
      }
      m.hide(false);
      m.setPosition(Math.round(p[0] - m.getWidth() / 2), Math.round(p[1] - m.getHeight() / 2));
      m.setZOrder(100000);
      const tapa = otros.some((o) => o !== s && !(o.isHidden && o.isHidden()) && dentro(caja(o), p[0], p[1], 2));
      m.setOpacity(tapa ? 110 : 210);
    }
    for (const m of objs(scn, "Mira")) {                            // miras de jugadores que ya no están
      if (!sups.some((s) => s.__fdizMira === m)) m.deleteFromScene(scn);
    }
  }

  // ------------------------------------------------------------------ munición en el HUD
  function hud(scn) {
    const st = scn.__fdizArmas || (scn.__fdizArmas = {});
    if (!st.dib) { st.dib = scn.createObject("BalasDib"); if (st.dib) { st.dib.setLayer("HUD"); st.dib.setPosition(0, 0); st.dib.setZOrder(60); } }
    const d = st.dib;
    if (d) d.clear();
    const intro = SV(scn, "Estado").getAsString() === "intro";
    for (const t of objs(scn, "TxtBalas")) {
      const j = num(t, "Jugador"), s = objs(scn, "Sup").find((o) => num(o, "Jugador") === j);
      const icono = objs(scn, "HudIcono").find((o) => num(o, "Jugador") === j && num(o, "Slot") === 3);
      const ver = !intro && s && A.deFuego(s) && num(s, "Usos") > 0 && (!icono || (icono.isVisible ? icono.isVisible() : !icono.isHidden()));
      if (!ver) { t.hide(true); continue; }
      const usos = Math.max(0, Math.round(num(s, "Usos"))), cap = Math.max(usos, A.CARGADOR[str(s, "Arma")]);
      const xy = A.ICONO[j] || [icono.getX(), icono.getY()];
      t.hide(false);
      if (t.getString() !== String(usos)) t.setText(String(usos));
      t.setColor(usos <= A.BAJAS ? "255;110;90" : "255;255;255");
      t.setPosition(xy[0] + 58, xy[1] + 10);
      if (!d) continue;
      // cargador: una marca por bala; las gastadas en gris (no hay reservas: solo lo que trae el arma)
      const w = 4, g = 2, total = cap * (w + g) - g, x0 = Math.round(xy[0] + 27 - total / 2), y0 = xy[1] + 57;
      d.setOutlineSize(1); d.setOutlineColor("20;20;30"); d.setOutlineOpacity(255); d.setFillOpacity(255);
      for (let k = 0; k < cap; k++) {
        d.setFillColor(k < usos ? "232;190;90" : "70;70;84");
        d.drawRectangle(x0 + k * (w + g), y0, x0 + k * (w + g) + w, y0 + 8);
      }
    }
  }

  // ------------------------------------------------------------------ pistola inicial en el piso (host / sin red)
  A.PISTOLA = {
    tipo: "pistolita",
    espera: 40,                 // cuadros después de que todos los Sup tienen Init = 1 (Historia y la intro ya los movieron)
    salones: [                  // muros del salón y dónde va la pistola (pies del arma), en el pasillo entre pupitres
      { zona: "B-01", x0: 5824, y0: 2848, x1: 6144, y1: 3264, x: 6000, y: 3100 },
      { zona: "E-04", x0: 4960, y0: 2368, x1: 5408, y1: 2624, x: 5200, y: 2570 },
    ],
  };
  const espera = new WeakMap();
  A.salonDe = function (x, y) {
    const S = A.PISTOLA.salones;
    const en = S.find((q) => x >= q.x0 && x <= q.x1 && y >= q.y0 && y <= q.y1);
    if (en) return en;
    const d = (q) => Math.hypot(x - (q.x0 + q.x1) / 2, y - (q.y0 + q.y1) / 2);
    return S.slice().sort((a, b) => d(a) - d(b))[0];
  };
  A.ponerPistola = function (scn) {
    if (rol(scn) === 2) return;
    const V = SV(scn, "PistolaPuesta");
    if (V.getAsNumber() !== 0) return;
    const sups = objs(scn, "Sup");
    if (!sups.length || sups.some((s) => num(s, "Init") !== 1)) return;
    const n = (espera.get(scn) || 0) + 1;
    espera.set(scn, n);
    if (n < A.PISTOLA.espera) return;
    const p1 = sups.find((s) => num(s, "Jugador") === 1) || sups[0];
    const q = A.salonDe(p1.getX(), p1.getY());
    const a = scn.createObject("ArmaPiso");
    if (!a) return;
    a.setLayer("Juego"); a.setPosition(q.x, q.y); a.setZOrder(q.y);
    VS(a, "Tipo").setString(A.PISTOLA.tipo); VS(a, "Solo").setNumber(1);
    a.setAnimationName(A.PISTOLA.tipo);
    V.setNumber(1);
  };

  // Fase 69: la pistola pequeña siempre se puede recoger. El sistema de siempre ("Armas del salón") solo recoge con los
  // puños; si el jugador trae un arma cuerpo a cuerpo (escoba, silla...) y pisa la pistola, esa arma se deja en el piso
  // y en este mismo cuadro el evento de siempre le da la pistola (y borra la del piso). Las armas de fuego no se cambian.
  A.cambiarPorPistola = function (scn) {
    if (rol(scn) === 2) return;
    for (const a of objs(scn, "ArmaPiso")) {
      if (str(a, "Tipo") !== A.PISTOLA.tipo) continue;
      const solo = num(a, "Solo");
      for (const s of objs(scn, "Sup")) {
        const arma = str(s, "Arma");
        if (arma === "puños" || A.deFuego(s) || str(s, "Estado") !== "normal" || (solo && num(s, "Jugador") !== solo)) continue;
        if (Math.hypot(s.getX() - a.getX(), s.getY() - a.getY()) > 40) continue;
        const d = scn.createObject("ArmaPiso");
        if (d) { d.setLayer("Juego"); d.setPosition(s.getX() - 56, s.getY() + 6); d.setZOrder(s.getY() + 6); VS(d, "Tipo").setString(arma); d.setAnimationName(arma); }
        VS(s, "Arma").setString("puños"); VS(s, "Usos").setNumber(0);
      }
    }
  };

  // ------------------------------------------------------------------ cada cuadro (todas las máquinas)
  A.tick = function (scn) {
    try { A.ponerPistola(scn); } catch (e) { /* sin la pistola inicial */ }
    try { A.cambiarPorPistola(scn); } catch (e) { /* sin armas en el piso */ }
    miras(scn);
    hud(scn);
  };
})(gdjs);

/*FDIZ-FASE56-MOD*/
/* FDI-Z · Fase 56 · Interacción con F (o A del mando): una sola acción a la vez.
 * Se incrusta en la escena Juego con scripts/fase56_interaccion.py (no editar el evento a mano: editar este archivo y volver a correr el script).
 * Define gdjs.fdizUsar.
 *
 * Antes, mantener Usar (F / A) hacía TODO lo que estuviera a su alcance a la vez: abrir una puerta, levantar a un caído,
 * curar a un mordido, usar un objetivo y revisar un locker. Además R abría puertas (y también lanza objetos).
 * Ahora, para cada jugador humano, este módulo elige UN objetivo interactuable:
 *   - candidatos dentro del alcance de cada acción (los mismos de los eventos): levantar a un caído 80 px, curar a un
 *     mordido 95 px, abrir una puerta 130 px (desde los pies al centro de la puerta), usar un objetivo 140 px y revisar un
 *     locker o mochila 95 px (centro a centro), hablar con un profe 115 px;
 *   - gana el de menor distancia relativa a su alcance (d / alcance); salvar a alguien pesa x0.75 (es urgente);
 *   - mientras se mantiene Usar se conserva el objetivo elegido (no salta a otro a la mitad), si sigue a su alcance.
 * Solo el elegido avanza: el módulo pone en el Sup una sola bandera Usa<Acción> = 1 y marca la puerta u objetivo elegido
 * (Elegida = 1). Los eventos de cada acción leen su bandera en vez de Usando. Puertas restringidas sin derribar
 * (TiempoAbrir 0) no se pueden abrir con F: solo se avisa. Los bots (y los profes aliados) siguen como antes: todas sus
 * banderas = Usando y todas las puertas / objetivos a su alcance quedan elegidos.
 * Indicación: "Mantén F para abrir" (A en mando) sobre cada jugador local, con barra de progreso mientras lo mantiene.
 * Autoridad: el host (o sin red) elige. Accion, UsarTxt y UsarProg se sincronizan; todos dibujan la indicación de sus
 * jugadores locales. */
(function (gdjs) {
  "use strict";
  if (gdjs.fdizUsar && gdjs.fdizUsar.VER === 1) return;
  const U = (gdjs.fdizUsar = { VER: 1 });

  U.CFG = {
    alcance: { revivir: 80, curar: 95, puerta: 130, objetivo: 140, cofre: 95, profe: 115, bloqueada: 130 },
    pesoSalvar: 0.75,      // levantar / curar ganan a una puerta u objeto que esté un poco más cerca
    revivirSeg: 3, curaSeg: 3, cofreSeg: 1,
  };
  const BANDERAS = { revivir: "UsaRevivir", curar: "UsaCurar", puerta: "UsaPuerta", objetivo: "UsaObjetivo", cofre: "UsaCofre" };
  const OBJ_TXT = {   // qué se hace con cada objetivo
    servidor: "prender el servidor", computadora: "llamar", llaves: "tomar las llaves", interruptor: "activar el interruptor",
    carnada: "dejar la comida", camion: "cargar la gasolina", canepa: "hablar con Canepa",
    h_telefono: "usar el teléfono", h_casillero: "revisar el casillero", h_cajon: "revisar el escritorio",   // fase 68 (Historia)
  };

  const V = (o, n) => o.getVariables().get(n);
  const num = (o, n) => V(o, n).getAsNumber();
  const str = (o, n) => V(o, n).getAsString();
  const lista = (scn, n) => scn.getObjects(n) || [];
  const dPos = (a, x, y) => Math.hypot(a.getX() - x, a.getY() - y);
  const dCentro = (a, b) => Math.hypot(a.getDrawableX() + a.getCenterX() - b.getDrawableX() - b.getCenterX(),
                                        a.getDrawableY() + a.getCenterY() - b.getDrawableY() - b.getCenterY());
  const humano = (s) => { const c = num(s, "Control"); return (c >= 0 || c === -3) && num(s, "Jugador") <= 4; };
  const nombreSup = (s) => { const j = num(s, "Jugador"); if (j <= 4) return "P" + j; const n = str(s, "Personaje"); return n ? n.charAt(0).toUpperCase() + n.slice(1) : "tu compañero"; };

  // ------------------------------------------------------------------ candidatos de un jugador
  function candidatos(scn, s, sups) {
    const A = U.CFG.alcance, out = [];
    for (const o of sups) {
      if (o === s) continue;
      const d = dPos(o, s.getX(), s.getY());
      if (str(o, "Estado") === "caido" && d < A.revivir) out.push({ t: "revivir", o, d, r: A.revivir });
      else if (str(o, "Estado") === "normal" && num(o, "Mordido") === 1 && d < A.curar) out.push({ t: "curar", o, d, r: A.curar });
    }
    for (const p of lista(scn, "Puerta")) {
      const d = dPos(s, p.getX() + p.getWidth() / 2, p.getY() + p.getHeight() / 2);
      if (d >= A.puerta) continue;
      if (num(p, "TiempoAbrir") > 0) out.push({ t: "puerta", o: p, d, r: A.puerta });
      else out.push({ t: "bloqueada", o: p, d, r: A.bloqueada });
    }
    for (const g of lista(scn, "Objetivo")) {
      if (num(g, "Hecho") !== 0 || num(g, "Tiempo") >= 999) continue;        // el camión del final no se "usa"
      if (gdjs.fdizHistoria && !gdjs.fdizHistoria.puedeUsar(scn, s, g)) continue;   // fase 69: Historia, solo desde dentro de la sala y con su puerta abierta
      const d = dCentro(s, g); if (d < A.objetivo) out.push({ t: "objetivo", o: g, d, r: A.objetivo });
    }
    for (const c of lista(scn, "Contenedor")) {
      if (num(c, "Abierto") !== 0) continue;
      const d = dCentro(s, c); if (d < A.cofre) out.push({ t: "cofre", o: c, d, r: A.cofre });
    }
    for (const p of lista(scn, "Profe")) {
      const e = str(p, "Estado"); if (e !== "espera" && e !== "conversacion") continue;
      if (gdjs.fdizCanepa && gdjs.fdizCanepa.reservado(scn, str(p, "Nombre"))) continue;   // fase 61: en Historia, primero la charla
      if (gdjs.fdizHistoria && gdjs.fdizHistoria.reservado(scn, str(p, "Nombre"))) continue;   // fase 68: los profes van por la historia
      const d = dPos(p, s.getX(), s.getY()); if (d < A.profe) out.push({ t: "profe", o: p, d, r: A.profe });
    }
    return out;
  }
  function puntaje(c) {
    let k = c.d / c.r;
    if (c.t === "revivir" || c.t === "curar") k *= U.CFG.pesoSalvar;
    if (c.t === "bloqueada") k += 1;                                         // solo avisa si no hay otra cosa
    return k;
  }
  function vigente(scn, s, c, sups) {   // el objetivo que se venía manteniendo, ¿sigue valiendo?
    if (!c || !c.o || c.o._livingOnScene === false) return null;
    const lst = candidatos(scn, s, sups);
    return lst.find((x) => x.o === c.o && x.t === c.t) || null;
  }

  function texto(c) {
    switch (c.t) {
      case "revivir": return "salvar a " + nombreSup(c.o);
      case "curar": return "curar a " + nombreSup(c.o);
      case "puerta": return str(c.o, "Tipo") === "electronica" && num(c.o, "TiempoAbrir") > 1 ? "abrir (electrónica, " + Math.round(num(c.o, "TiempoAbrir")) + " s)" : "abrir";
      case "objetivo": return OBJ_TXT[str(c.o, "Tipo")] || "usar";
      case "cofre": return "revisar";
      case "bloqueada": { const v = c.o.getVariables(), q = v.has && v.has("Bloqueo") ? str(c.o, "Bloqueo") : ""; return q && q !== "0" ? q : "!Puerta restringida: derríbala a golpes"; }   // fase 68: Bloqueo = aviso propio (Historia)
      default: return "";
    }
  }
  function progreso(c) {
    const o = c.o, K = U.CFG;
    switch (c.t) {
      case "revivir": return num(o, "Revivir") / K.revivirSeg;
      case "curar": return num(o, "Cura") / K.curaSeg;
      case "puerta": return num(o, "TiempoAbrir") > 0 ? num(o, "Progreso") / num(o, "TiempoAbrir") : 0;
      case "objetivo": return num(o, "Tiempo") > 0 ? num(o, "Progreso") / num(o, "Tiempo") : 0;
      case "cofre": return num(o, "Progreso") / K.cofreSeg;
      default: return 0;
    }
  }

  // ------------------------------------------------------------------ host / sin red: elegir (antes de las puertas)
  U.elegir = function (scn) {
    const st = scn._fdizUsar || (scn._fdizUsar = { fijo: new Map(), soltar: new Set() });
    const sups = lista(scn, "Sup");
    for (const p of lista(scn, "Puerta")) V(p, "Elegida").setNumber(0);
    for (const g of lista(scn, "Objetivo")) V(g, "Elegida").setNumber(0);
    for (const s of sups) {
      const usa = num(s, "Usando") === 1 && str(s, "Estado") === "normal";
      if (!humano(s)) {                                     // bots y profes: como antes
        for (const k in BANDERAS) V(s, BANDERAS[k]).setNumber(usa ? 1 : 0);
        if (usa) {
          for (const p of lista(scn, "Puerta")) if (dPos(s, p.getX() + p.getWidth() / 2, p.getY() + p.getHeight() / 2) < U.CFG.alcance.puerta) V(p, "Elegida").setNumber(1);
          for (const g of lista(scn, "Objetivo")) if (dCentro(s, g) < U.CFG.alcance.objetivo && !(gdjs.fdizHistoria && !gdjs.fdizHistoria.puedeUsar(scn, s, g))) V(g, "Elegida").setNumber(1);
        }
        V(s, "Accion").setString(""); V(s, "UsarTxt").setString(""); V(s, "UsarProg").setNumber(0);
        continue;
      }
      let c = null;
      if (!usa) st.soltar.delete(s);
      if (str(s, "Estado") === "normal") {
        const prev = st.fijo.get(s);
        c = usa && prev ? vigente(scn, s, prev, sups) : null;
        // terminó (o se fue de alcance) lo que se venía manteniendo: hay que soltar F antes de empezar otra cosa,
        // así una misma pulsación nunca salva a alguien y luego abre una puerta
        if (usa && prev && !c) st.soltar.add(s);
        if (!c) {
          let best = null, bk = 1e9;
          for (const x of candidatos(scn, s, sups)) { const k = puntaje(x); if (k < bk) { bk = k; best = x; } }
          c = best;
        }
