  }
  if (U.open) {
    V.get("ProfDlg").setNumber(1);   // bloquea la pausa (Esc / P / Start) mientras el cuadro está abierto
    const cur = { clic: I.isMouseButtonPressed(0), k: [13, 32, 27].some((c) => I.isKeyPressed(c)), a: false };
