  if (f > 0 && !libre(z.getX() + ox, z.getY() + oy)) { v.get("OffX").setNumber(0); v.get("OffY").setNumber(0); } else { v.get("OffX").setNumber(ox); v.get("OffY").setNumber(oy); }
